    'CBA A3 puis COMSPEC Overwatch dans le launcher.' => 'CBA A3 then COMSPEC Overwatch in the launcher.',
    'Ce bloc est indépendant de la fiche : il enregistre seulement une nouvelle rubrique dans la liste, puis vous pourrez la choisir ci-dessous après actualisation si besoin.' => 'This block is independent of the record: it only saves a new category in the list, then you can select it below after refreshing if needed.',
    'Ce choix définit le parcours candidat sur la page d’enrôlement public. Vous pourrez le modifier ensuite.' => 'This choice defines the applicant flow on the public enlistment page. You can change it afterward.',
    'Ce code de connexion a expiré ou n’est plus valide. Générez-en un nouveau depuis Athena sur l’ordinateur (bouton' => 'This connection code has expired or is no longer valid. Generate a new one from Athena on the computer (button',
    'Ce compte rendu porte des éléments de scénario non vérifiés. Un score de similarité ou un verdict de terminal n’est pas une identification établie. Les textes ci-dessous sont générés à la lecture — pour diffuser, ouvrez un brouillon dans l’atelier de rédaction.' => 'This report contains unverified scenario elements. A similarity score or terminal verdict is not an established identification. The texts below are generated on read — to distribute, open a draft in the drafting workshop.',
    'Ce contenu peut être trompeur. Ne le présentez pas comme un fait confirmé.' => 'This content may be misleading. Do not present it as a confirmed fact.',
    'Ce créneau et les %1 suivant%2 de la série' => 'This slot and the %1 following%2 in the series',
    'Ce créneau fait partie d’une série' => 'This slot is part of a series',
    'Ce créneau seulement' => 'This slot only',
    'Ce document atteste que' => 'This document certifies that',
    'Ce document atteste que le titulaire a validé le parcours « %1 » avec sérieux et rigueur. Cette réussite témoigne d’une bonne maîtrise des enseignements et d’un engagement soutenu tout au long du parcours.' => 'This document certifies that the holder has completed the “%1” path with diligence and rigor. This achievement reflects a good command of the material and a sustained commitment throughout the path.',
    'Ce document est marqué comme obsolète (revue/correction requise).' => 'This document is marked as obsolete (review/correction required).',
    'Ce document est servi au niveau de votre habilitation. Pour produire une version destinée à un cercle plus large, passez par la' => 'This document is served at your clearance level. To produce a version for a wider circle, go through the',
    'Ce dossier est marqué comme non déployable : la personne n’apparaît pas comme disponible pour un déploiement.' => 'This file is marked as non-deployable: the person does not appear as available for deployment.',
    'Ce dossier est protégé par un code secret d’ouverture, distinct du code d’accès au portail. Saisissez-le pour consulter le contenu pendant cette session.' => 'This case file is protected by a secret opening code, separate from the portal access code. Enter it to view the contents during this session.',
    'Ce dossier est tenu au-dessus de votre habilitation : les catégories trop élevées restent noircies.' => 'This file is held above your clearance: categories that are too high remain blacked out.',
    'Ce guide vous accompagne pour constituer votre dossier opérationnel : identité de personnage, unité, rôle, équipement suggéré et ce que les autres voient de vous sur le forum. Lisez les sections dans l’ordre si vous démarrez, ou sautez à celle qui correspond à votre question du moment.' => 'This guide walks you through building your operational record: character identity, unit, role, suggested equipment, and what others see of you on the forum. Read the sections in order if you are just starting, or jump to the one that matches your current question.',
    'Ce lien ne peut plus être utilisé. Ouvre plutôt le message ou le sujet d’origine et reclique sur le lien externe.' => 'This link can no longer be used. Open the original message or topic instead and click the external link again.',
    'Ce lien n’est plus valable. Demandez une nouvelle invitation à votre encadrement.' => 'This link is no longer valid. Ask your leadership for a new invitation.',
    'Ce lien ouvre un site externe, hors du portail — reste prudent·e.' => 'This link opens an external site, outside the portal — stay cautious.',
    'Ce manuel est accessible depuis la navigation (' => 'This manual is accessible from the navigation (',
    'Ce mur n’est plus disponible' => 'This wall is no longer available',
    'Ce mur reprend les missions et dispositifs ouverts sur le tableau opérationnel. Les activités de formation et les informations pratiques restent sur leurs propres écrans.' => 'This wall shows the missions and deployments open on the operations board. Training activities and practical information stay on their own screens.',
    'Ce niveau indique jusqu’où l’opérateur peut lire le renseignement classifié. L’entrée au portail reste régie par les droits d’accès ou, pour les invités, par un code temporaire.' => 'This level indicates how far the operator can read classified intelligence. Portal entry remains governed by access rights or, for guests, by a temporary code.',
    'Ce n’est pas une preuve' => 'This is not proof',
    'Ce paquet n’est plus dans la file d’exploitation (%1).' => 'This packet is no longer in the exploitation queue (%1).',
    'Ce portail d’enrôlement est lié à une communauté précise. Sans organisation cible, le dossier ne peut pas être ouvert.' => 'This enlistment portal is tied to a specific community. Without a target organization, the application cannot be opened.',
    'Ce que couvre le bureau' => 'What the desk covers',
    'Ce que la carte a vu pendant cette session : pannes d’affichage et données reçues du terrain.' => 'What the map saw during this session: display failures and data received from the field.',
    'Ce que la communauté met à disposition — et comment y accéder.' => 'What the community provides — and how to access it.',
    'ce que la personne fait' => 'what the person does',
    'Ce que les autres voient de vous' => 'What others see of you',
    'Ce que les destinataires doivent retenir' => 'What recipients should remember',
    'Ce que les visiteurs et les membres verront en premier sur Athena.' => 'What visitors and members will see first on Athena.',
    'Ce que l’on peut faire de ce dossier' => 'What can be done with this case file',
    'Ce que l’organisation a modifié sur cette fiche : grade, rôles, statut du compte, coordonnées. Rien n’est effacé : chaque enregistrement s’ajoute à la liste.' => 'What the organization changed on this record: rank, roles, account status, contact details. Nothing is deleted: each entry is added to the list.',
    'Ce que l’organisation a modifié sur la fiche : grade, rôles, statut du compte, coordonnées.' => 'What the organization changed on the record: rank, roles, account status, contact details.',
    'Ce que voit l’encadrement' => 'What leadership sees',
    'Ce que voit un membre' => 'What a member sees',
    'Ce que votre poste attend de vous : tâches affectées, validations, puis le reste du briefing personnel.' => 'What your position expects of you: assigned tasks, approvals, then the rest of your personal briefing.',
    'Ce que vous devez faire, et ce que l’encadrement valide.' => 'What you need to do, and what leadership validates.',
    'Ce que vous en faites, en une phrase' => 'What you do with it, in one sentence',
    'Ce que vous observez in-game' => 'What you observe in game',
    'Ce que vous pouvez faire dans cette communauté dépend de votre rôle.' => 'What you can do in this community depends on your role.',
    'Ce que vous voulez consigner' => 'What you want to record',
    'Ce qui a bien fonctionné' => 'What worked well',
    'Ce qui a fonctionné, écarts, recommandations…' => 'What worked, gaps, recommendations…',
    'Ce qui a gêné' => 'What got in the way',
    'Ce qui a moins fonctionné' => 'What worked less well',
    'Ce qui a été vu ou saisi' => 'What was seen or seized',
    'Ce qui attend une réponse de votre part, et les liaisons en cours.' => 'What is awaiting a response from you, and current links.',
    'Ce qui demande attention' => 'What needs attention',
    'Ce qui descend du commandement, ce qui circule dans l’unité, ce qui remonte.' => 'What comes down from command, what circulates within the unit, what goes up.',
    'Ce qui est disponible en 1.4.0' => 'What is available in 1.4.0',
    'Ce qui est déjà enregistré sur le dossier.' => 'What is already recorded on the file.',
    'Ce qui justifie d’interrompre le poste de commandement' => 'What justifies interrupting the command post',
    'Ce qui relie les personnes, les sites, les pièces, les saisies, les pièces à conviction et les documents du dossier. Les liens' => 'What connects the file’s people, sites, items, seizures, exhibits and documents. The links',
    'Ce qui remonte automatiquement' => 'What is reported automatically',
    'Ce qui reste à déterminer' => 'What remains to be determined',
    'Ce qui vous est vraiment utile' => 'What is really useful to you',
    'Ce qu’elle couvre' => 'What it covers',
    'Ce qu’en disent les membres' => 'What members say',
    'Ce qu’il faut' => 'What you need',
    'Ce qu’il faut encore obtenir ou confirmer.' => 'What still needs to be obtained or confirmed.',
    'Ce qu’une fiche n’est pas' => 'What a record is not',
    'Ce réglage servira de référence par défaut pour l’ensemble des modules dépendants du temps.' => 'This setting will serve as the default reference for all time-dependent modules.',
    'Ce résumé reprend le dossier ouvert au bureau SSE. Les photographies, lieux et recoupements se consultent sur la fiche complète.' => 'This summary reflects the file open in the SSE office. Photographs, locations, and cross-references can be viewed on the full record.',
    'Ce sujet est hébergé par une autre communauté. Tant que vous n’avez pas validé votre autorisation de partage (code par e-mail), ou si le fil est clos, vous êtes en' => 'This topic is hosted by another community. Until you have validated your sharing authorization (code by email), or if the thread is closed, you are in',
    'Ce sujet est hébergé par une autre communauté. Vous consultez une copie de travail en' => 'This topic is hosted by another community. You are viewing a working copy in',
    'Ce sujet est verrouillé ou archivé. Les nouvelles réponses ne sont pas acceptées.' => 'This topic is locked or archived. New replies are not accepted.',
    'Ce sujet est verrouillé — les nouvelles réponses ne sont pas acceptées.' => 'This topic is locked — new replies are not accepted.',
    'Ceci est un aperçu de la feuille telle qu’elle apparaît à la rédaction.\\n\\nModifiez le bandeau, le pied de page ou l’aspect du papier à gauche : le rendu se met à jour après enregistrement.' => 'This is a preview of the sheet as it appears in the drafting screen.\\n\\nEdit the banner, footer or paper appearance on the left: the rendering updates after saving.',
    'Ceci n\'est pas une inscription automatique. Toute soumission est examinée par la cellule de recrutement et validée ou rejetée par le commandement.' => 'This is not an automatic registration. Every submission is reviewed by the recruitment cell and approved or rejected by command.',
    'Cellule / équipe' => 'Cell / team',
    'Centralisez le recrutement, la présence, les formations et la coordination opérationnelle.' => 'Centralize recruitment, attendance, training and operational coordination.',
    'Centre de commandement' => 'Command center',
    'Centre de pilotage' => 'Control center',
    'Centre d’opérations' => 'Operations center',
    'CENTRE SSE' => 'SSE CENTER',
    'Centre SSE' => 'SSE Center',
    'Centrer sur la carte' => 'Center on map',
    'Cercle en pointillés : distance qu’un contact a pu parcourir depuis le dernier point connu' => 'Dotted circle: distance a contact could have traveled since the last known point',
    'Cercles autour du contact ouvert. Distances en mètres sur le théâtre.' => 'Circles around the open contact. Distances in meters on the theater.',
    'Certaines communautés imposent un item ou une tablette pour utiliser Overwatch. Si le hub reste inaccessible, demandez à votre encadrement si cette règle s’applique à votre mission.' => 'Some communities require an item or tablet to use Overwatch. If the hub remains inaccessible, ask your leadership whether this rule applies to your mission.',
    'Certaines configurations ou données peuvent être modifiées pendant cette intervention.' => 'Some settings or data may be modified during this intervention.',
    'Certaines vues ne vous sont pas ouvertes' => 'Some views are not open to you',
    'Certaines vues permettent d’envoyer des images de reconnaissance avec position et cap vers le portail.' => 'Some views let you send reconnaissance images with position and heading to the portal.',
    'Certains emplois métier' => 'Certain job roles',
    'Certifiant' => 'Certifying',
    'Certificat non trouvé.' => 'Certificate not found.',
    'Certificat, réalisme, état matériel' => 'Certificate, realism, hardware status',
    'Certificats terminaux' => 'Terminal certificates',
    'Certifié' => 'Certified',
    'Ces catégories restent désactivées tant que vous n’avez pas donné votre accord.' => 'These categories remain disabled until you have given your consent.',
    'Ces entrées reflètent les envois opérateurs. Elles ne remplacent pas la qualification en dossier d’intérêt ou dossier validé.' => 'These entries reflect operator submissions. They do not replace qualification as a file of interest or validated case file.',
    'Ces mentions sont des propositions. Elles n’ouvrent pas un lien dans la toile tant qu’un analyste ne les a pas validées.' => 'These mentions are proposals. They do not open a link in the web until an analyst has validated them.',
    'Ces modèles créent les profils de départ de votre organisation (commandement, ressources humaines, instruction, membres, invités et modération du forum). Vous pourrez les ajuster à tout moment après la création.' => 'These templates create your organization’s starting profiles (command, human resources, training, members, guests, and forum moderation). You can adjust them at any time after creation.',
    'Ces personnes ne peuvent pas ouvrir ce dossier, même si elles font partie de la cellule.' => 'These persons cannot open this case file, even if they are part of the cell.',
    'Ces profils accélèrent une candidature : ils ne remplacent pas votre fiche personnelle ni votre compte civil.' => 'These profiles speed up an application: they do not replace your personnel file or your civilian account.',
    'Ces réglages s’appliquent aux personnes qui consultent l’ORBAT selon leurs affectations. Les gestionnaires voient toujours la structure complète pour le pilotage.' => 'These settings apply to people viewing the ORBAT based on their assignments. Managers always see the full structure for oversight.',
    'Ces traceurs sont indispensables au fonctionnement de base : maintien de session, protection anti-CSRF des formulaires, équilibrage technique, sécurité et mémorisation de préférences critiques.' => 'These trackers are essential for basic operation: session maintenance, CSRF protection of forms, technical load balancing, security, and storing critical preferences.',
    'Ces traceurs sont indispensables au fonctionnement de base : maintien de session, protection des formulaires, équilibrage technique, sécurité et mémorisation de préférences critiques.' => 'These trackers are essential for basic operation: session maintenance, form protection, technical load balancing, security, and storing critical preferences.',
    'Ces trois niveaux suffisent-ils pour votre communauté ?' => 'Are these three levels enough for your community?',
    'Cet écran est la' => 'This screen is the',
    'Cet écran est le' => 'This screen is the',
    'Cette action est définitive. Les sous-unités doivent être déplacées ou supprimées avant. Si l’unité a un historique, préférez l’archivage.' => 'This action is permanent. Sub-units must be moved or deleted first. If the unit has a history, archiving is preferable.',
    'Cette candidature n’a pas été retenue. Les échanges et l’envoi de pièces sont désactivés.' => 'This application was not selected. Messaging and file uploads are disabled.',
    'Cette collection s’ouvre dans le catalogue.' => 'This collection opens in the catalog.',
    'cette communauté' => 'this community',
    'Cette communauté commence aujourd’hui' => 'This community starts today',
    'Cette communauté n’a pas encore activé le formulaire de bilan sur son installation.' => 'This community has not yet enabled the debrief form on its installation.',
    'Cette communauté n’a pas encore rédigé de présentation courte. Ouvrez la fiche publique pour en savoir plus sur le recrutement et la vie de l’unité.' => 'This community has not written a short introduction yet. Open the public page to learn more about recruitment and unit life.',
    'Cette communauté n’utilise pas le dossier MilSim complet. Remplissez le' => 'This community does not use the full MilSim file. Fill out the',
    'Cette coopération mentionne les besoins suivants. La couverture réelle dépend des dossiers de chaque unité (à confirmer avec vos référents).' => 'This cooperation lists the following requirements. Actual coverage depends on each unit’s records (to be confirmed with your points of contact).',
    'Cette date sert au calcul d’ancienneté du fondateur et des membres. Vous pourrez la modifier ensuite.' => 'This date is used to calculate the seniority of the founder and members. You can change it afterward.',
    'Cette documentation HTML n’existe pas, n’est pas encore publiée, ou n’est plus disponible pour votre communauté.' => 'This HTML documentation does not exist, is not yet published, or is no longer available for your community.',
    'Cette démonstration est réalisée par' => 'This demo is produced by',
    'Cette démonstration n’est plus accessible depuis votre connexion. La fenêtre d’entrée ou la durée d’accès autorisée est écoulée.' => 'This demo is no longer accessible from your connection. The entry window or the authorized access time has elapsed.',
    'cette entrée' => 'this entry',
    'Cette entrée est antérieure à l’enregistrement détaillé du contenu. Les prochaines transmissions depuis Arma afficheront ici l’identité, les relevés et la version du pack (ex. COMSPEC Overwatch v1.4.17).' => 'This entry predates detailed content recording. Future transmissions from Arma will display the identity, readings, and pack version here (e.g. COMSPEC Overwatch v1.4.17).',
    'Cette fiche personnel n’est plus accessible. <a class="underline font-semibold" href="' => 'This personnel file is no longer accessible. <a class="underline font-semibold" href="',
    'Cette fonction sera disponible après la prochaine mise à jour de la base de données.' => 'This feature will be available after the next database update.',
    'Cette formation n’existe pas dans votre communauté, ou n’est plus accessible.' => 'This training does not exist in your community, or is no longer accessible.',
    'Cette interface est un' => 'This interface is a',
    'Cette option sera disponible après la prochaine mise à jour de la base de données sur ce serveur.' => 'This option will be available after the next database update on this server.',
    'Cette page décrit l’usage des cookies et mécanismes équivalents déposés ou lus sur votre terminal (ordinateur, mobile, tablette), ainsi que la façon dont nous mémorisons votre choix de consentement.' => 'This page describes the use of cookies and equivalent mechanisms placed or read on your device (computer, mobile, tablet), as well as how we store your consent choice.',
    'Cette page n’est pas encore prête sur cette instance. Demandez à l’administration d’appliquer la mise à jour, puis rechargez.' => 'This page is not ready on this instance yet. Ask the administration to apply the update, then reload.',
    'Cette page se recharge automatiquement.' => 'This page reloads automatically.',
    'Cette page s’adresse à toutes les personnes qui utilisent %1 — membres, administrateurs de communauté et visiteurs. Vous y trouverez les conditions d’utilisation du service, les règles applicables aux offres payantes, le traitement de vos données personnelles, les mentions légales et la gestion des cookies.' => 'This page is intended for everyone who uses %1 — members, community administrators, and visitors. Here you will find the terms of use of the service, the rules applicable to paid offers, the processing of your personal data, the legal notice, and cookie management.',
    'Cette proposition a été annulée%1. Vous pouvez la dupliquer depuis la synthèse pour repartir de son cadrage.' => 'This proposal was canceled%1. You can duplicate it from the summary to start over from its framing.',
    'Cette rubrique décrit l’usage des cookies et mécanismes équivalents déposés ou lus sur votre terminal, ainsi que la façon dont nous mémorisons votre choix de consentement.' => 'This section describes the use of cookies and equivalent mechanisms placed or read on your device, as well as how we store your consent choice.',
    'Cette semaine' => 'This week',
    'Cette structure est temporaire. Elle ne modifie pas l’organigramme administratif de la communauté.' => 'This structure is temporary. It does not change the community’s administrative org chart.',
    'Cette tentative n’existe pas, a expiré, ou ne vous appartient pas. Ouvrez le quiz depuis la fiche de votre formation.' => 'This attempt does not exist, has expired, or does not belong to you. Open the quiz from your training sheet.',
    'Cette tenue s’envoie et se récupère depuis l’arsenal en jeu, bandeau Athena en haut de l’écran d’équipement.' => 'This loadout is sent and retrieved from the in-game arsenal, Athena banner at the top of the equipment screen.',
    'Cette unité fait partie de %1.' => 'This unit is part of %1.',
    'Cette version évolue. Dites-nous ce qui est clair, ce qui bloque, et si les trois niveaux d’accès (Membre, Ressources humaines, Gestionnaire) suffisent pour votre communauté.' => 'This version is evolving. Tell us what is clear, what is blocking, and whether the three access levels (Member, Human Resources, Manager) are enough for your community.',
    'Cette version évolue. Dites-nous ce qui est clair, ce qui bloque, et si les trois niveaux d’accès suffisent.' => 'This version is evolving. Tell us what is clear, what blocks you, and whether the three access levels are enough.',
    'Cette vidéo ne peut pas être intégrée ici.' => 'This video cannot be embedded here.',
    'Cette vue ne montre que les calques publiés. Le travail encore en brouillon reste dans le plan.' => 'This view shows published layers only. Work still in draft stays in the plan.',
    'Cette zone sert au texte de présentation plus détaillé sous le bandeau.' => 'This area is for the more detailed introduction text below the banner.',
    'Chaleur de présence' => 'Presence heat map',
    'Champ' => 'Field',
    'Champ de mines' => 'Minefield',
    'Champ d’application' => 'Scope',
    'Champs adaptés au type sélectionné — renseignez ce qui est connu, laissez le reste vide.' => 'Fields adapted to the selected type — fill in what is known, leave the rest blank.',
    'Champs du dossier' => 'File fields',
    'Champs optionnels non renseignés' => 'Optional fields not filled in',
    'Champs réduits (mode simple).' => 'Reduced fields (simple mode).',
    'Changement d’étape' => 'Stage change',
    'Changements' => 'Changes',
    'Changements appliqués' => 'Changes applied',
    'Changer de communauté (plusieurs communautés disponibles)' => 'Switch community (several communities available)',
    'Changer de mot de passe ferme aussi les autres sessions. Les téléphones ATAK se gèrent dans' => 'Changing your password also signs out your other sessions. ATAK phones are managed in',
    'Changer de poste ou d’unité' => 'Change position or unit',
    'Changer de type (nouvelle fiche)' => 'Change type (new record)',
    'Changer le compte Steam' => 'Change Steam account',
    'Changer le mot de passe' => 'Change password',
    'Changer le secret d’accès' => 'Change access secret',
    'Changer l’unité, l’emploi, le grade ou la date d’engagement envoie une demande. Rien n’est écrit sur le dossier tant qu’un responsable n’a pas confirmé.' => 'Changing the unit, job, rank or enlistment date sends a request. Nothing is written to the file until a leader has confirmed.',
    'Changez de type pour recharger le modèle guidé (si le corps n’a pas encore été personnalisé). Évitez les noms en clair si une diffusion large est prévue. Pour une version expurgée à partir d’un dossier, utilisez aussi l’écran de déclassification.' => 'Change the type to reload the guided template (if the body has not yet been customized). Avoid plain names if wide distribution is planned. For a redacted version from a case file, also use the declassification screen.',
    'Changez le secret utilisé pour vous connecter. Minimum 8 caractères.' => 'Change the secret used to sign in. Minimum 8 characters.',
    'Chaque bouton ouvre l’éditeur en brouillon, avec la date du jour. Complétez, validez, puis mettez en ligne.' => 'Each button opens the editor as a draft, with today’s date. Complete it, validate it, then publish it.',
    'Chaque communauté peut couper le lien à tout moment.' => 'Each community can cut the link at any time.',
    'Chaque document porte une classification. Une diffusion plus large passe par une version expurgée et une validation explicite — jamais par copie libre.' => 'Each document carries a classification. Wider distribution goes through a redacted version and explicit validation — never through free copying.',
    'Chaque durée ci-dessous correspond à des' => 'Each duration below corresponds to',
    'Chaque décision est journalisée avec son auteur, son horodatage et sa justification.' => 'Each decision is logged with its author, timestamp and justification.',
    'Chaque fiche est un objet réutilisable : dossiers, toiles, chronologie et carte s’appuient sur le même registre — pas un formulaire isolé.' => 'Each record is a reusable object: case files, webs, timeline, and map all rely on the same registry — not an isolated form.',
    'Chaque investigation est une toile d’hypothèses : identités, sites, matériels et liens. Vous pouvez en ouvrir plusieurs, puis les regrouper en une seule quand les pistes convergent.' => 'Each investigation is a web of hypotheses: identities, sites, equipment, and links. You can open several, then merge them into one when the leads converge.',
    'Chaque ligne correspond à un terminal qui s’est présenté avec votre compte. Retirer un appareil l’empêche de se reconnecter jusqu’à une nouvelle association.' => 'Each row is a device that has connected with your account. Removing a device prevents it from reconnecting until it is paired again.',
    'Chaque membre voit les tenues enregistrées depuis l’arsenal en jeu. Envoyez les vôtres depuis le bandeau Athena, en haut de l’écran d’équipement.' => 'Every member sees the loadouts saved from the in-game arsenal. Send yours from the Athena banner at the top of the equipment screen.',
    'Chaque mode correspond à un écran de saisie différent juste en dessous. Choisissez celui qui correspond à votre besoin.' => 'Each mode corresponds to a different entry screen just below. Choose the one that fits your need.',
    'Chaque opération rassemble le plan, le renseignement, les ordres et la vue terrain. La carte ATAK affiche ce qui a été publié, pas le travail d’état-major encore en cours.' => 'Each operation brings together the plan, intelligence, orders, and the ground view. The ATAK map shows what has been published, not the staff work still in progress.',
    'Chaque ouverture de session, chaque consultation sensible et chaque rédaction sont journalisées. Vous en êtes responsable.' => 'Every session opening, every sensitive access and every drafting action is logged. You are responsible for it.',
    'Chaque point complété améliore la lisibilité de votre dossier pour l’encadrement et les outils du portail.' => 'Each completed item improves the readability of your record for leadership and portal tools.',
    'Chaque réponse correcte se verrouille tout de suite. Quand tous les champs sont validés, utilisez « Suivant » pour continuer.' => 'Each correct answer locks immediately. When all fields are validated, use “Next” to continue.',
    'Chaque sous-unité a son espace. Ce qu’elle remonte apparaît ici dans « Dans l’unité ».' => 'Each subunit has its own space. What it escalates appears here under “Within the unit”.',
    'Chaque type ouvre un écran dédié : les textes d’aide et les blocs proposés correspondent à l’activité choisie. Vous pourrez ensuite préciser' => 'Each type opens a dedicated screen: the help texts and proposed blocks match the chosen activity. You can then specify',
    'Chaque unité de la chaîne de commandement aura ici son propre espace.' => 'Each unit in the chain of command will have its own space here.',
