    'pour les apprenants.' => 'for learners.',
    'Pour les données personnelles traitées via des traceurs, vous disposez des droits prévus par le RGPD (accès, rectification, effacement, opposition, limitation, portabilité selon les cas).' => 'For personal data processed via trackers, you have the rights provided by the GDPR (access, rectification, erasure, objection, restriction, portability, depending on the case).',
