    'Pour les équipes qui gèrent une communauté' => 'For teams that manage a community',
    'Pour limiter les copies d’écran, l’affichage du document a été masqué.' => 'To limit screenshots, the document display has been hidden.',
    'pour lui — ni la fiche, ni les personnes rattachées, ni les notes, ni les corrélations, ni le compte rendu.' => 'for them — not the sheet, nor the attached persons, nor the notes, nor the correlations, nor the after-action report.',
