    'Pour postuler' => 'To apply',
    'Pour protéger votre vie privée, votre adresse e-mail n’apparaît pas sur votre fiche pour les autres membres. Elle reste visible pour vous et pour le personnel habilité (gestion des effectifs ou accès RH sensible).' => 'To protect your privacy, your email address does not appear on your record for other members. It remains visible to you and to authorized staff (personnel management or sensitive HR access).',
