    'pour qu’ils puissent vous attribuer les habilitations adaptées.' => 'so that they can assign you the appropriate clearances.',
    'Pour rappel : les administrateurs de votre communauté peuvent aussi traiter certaines demandes qui ne concernent que l’activité interne de cette communauté. En cas d’urgence liée à la sécurité de votre compte, changez votre mot de passe et contactez le support selon les' => 'As a reminder: your community’s administrators can also handle certain requests that only concern the internal activity of that community. In case of urgency related to your account’s security, change your password and contact support according to the',
