    'Pour toute autre demande relative à vos données personnelles (rectification, effacement complet, opposition…), utilisez le formulaire dédié depuis les mentions légales.' => 'For any other request concerning your personal data (rectification, full erasure, objection…), use the dedicated form from the legal notices.',
