    'Selon l’endroit où vous écrivez, la carte d’auteur n’affiche pas les mêmes informations. Votre dossier contrôle surtout ce qui apparaît dans l’espace de votre communauté.' => 'Depending on where you write, the author card does not show the same information. Your record mainly controls what appears in your community’s space.',
