    'Votre compréhension de l’engagement (accountability)' => 'Your understanding of the commitment (accountability)',
    'Votre compte a été désactivé le %1 et sera anonymisé définitivement le %2. Tant que le compte n’est pas anonymisé, vous pouvez annuler la suppression en vous reconnectant.' => 'Your account was deactivated on %1 and will be permanently anonymized on %2. As long as the account is not anonymized, you can cancel the deletion by signing back in.',
    'Votre compte est reconnu pour le renseignement. Vous pouvez entrer sans code, ou saisir un code temporaire pour une session invitée.' => 'Your account is recognized for intelligence. You can enter without a code, or enter a temporary code for a guest session.',
    'Votre compte fondateur est en service actif.' => 'Your founder account is on active duty.',
    'Votre compte sera immédiatement désactivé, puis anonymisé définitivement après un délai de rétractation de %1 jours. Vous pouvez annuler à tout moment pendant ce délai en vous reconnectant.' => 'Your account will be deactivated immediately, then permanently anonymized after a withdrawal period of %1 days. You can cancel at any time during this period by signing back in.',
