    'Votre rôle' => 'Your role',
    'Votre rôle applique déjà un code par e-mail lorsque l’application d’authentification n’est pas utilisée. Vous n’avez rien à activer ici.' => 'Your role already enforces an email code when the authenticator app is not used. You have nothing to enable here.',
    'Votre rôle dans la communauté et le suivi de vos demandes d’élévation.' => 'Your role in the community and the status of your elevation requests.',
    'Votre rôle de session' => 'Your session role',
    'Votre signalement est confidentiel. Les modérateurs de la communauté en sont informés.' => 'Your report is confidential. The community moderators are notified.',
    'Votre situation' => 'Your situation',
    'Votre situation aujourd’hui' => 'Your situation today',
    'Votre staff peut simuler un environnement radio dégradé : couverture inégale, matériel endommagé, reprise après crash. Tout est configurable par communauté sur le portail.' => 'Your staff can simulate a degraded radio environment: uneven coverage, damaged equipment, crash recovery. Everything is configurable per community on the portal.',
    'Votre temps en mission : %1' => 'Your mission time: %1',
    'Votre terminal vibre lorsque vous (indicatif de session) approchez d’un téléphone suivi, dans le rayon choisi sur ce poste ou sur l’ATAK en jeu.' => 'Your terminal vibrates when you (session callsign) approach a tracked phone, within the radius chosen on this station or on in-game ATAK.',
    'Votre téléphone est relié à la communauté. Choisissez l’écran à afficher.' => 'Your phone is linked to the community. Choose the screen to display.',
    'Votre unité' => 'Your unit',
    'Votre unité n’a pas encore choisi de tenue de référence. Toutes les tenues restent consultables dans l’équipement.' => 'Your unit has not chosen a reference uniform yet. All uniforms remain viewable in the equipment section.',
    'Votre unité n’a pas encore publié de parcours. Le catalogue complet reste accessible.' => 'Your unit has not published a pathway yet. The full catalog remains accessible.',
    'Votre validation : %1' => 'Your validation: %1',
